package com.nur.quran.data.planner

import com.google.gson.JsonParser
import org.junit.Assert.*
import org.junit.Test
import java.io.File

/** Expected values generated by the web planner functions, rather than reimplemented in the test. */
class WebRebalanceNumbersFixtureTest {
    @Test fun `native schedule dates and displayed counts match actual web outputs`() {
        val cases = JsonParser.parseString(File("src/test/resources/fixtures/web-rebalance-numbers.json").readText()).asJsonArray
        for (entry in cases) {
            val c = entry.asJsonObject
            val today = c["today"].asString
            val original = PlannerEngine.buildReadingPlanner(
                unitType = "page", durationDays = 1, startDate = today,
                startUnit = 1, endUnit = c["total"].asInt, chapters = emptyList()
            ).copy(
                excludeDays = c["excluded"].asJsonArray.map { it.asInt },
                assignmentReadPages = if (c["partial"].asInt > 0) mapOf(1 to (1..c["partial"].asInt).toList()) else emptyMap()
            )
            val native = PlannerEngine.rebalancePlanner(original, c["strategy"].asString, c["days"].asInt, today)
            val label = "${c["strategy"]}, ${c["total"]} pages, ${c["days"]} days"
            assertEquals(label, c["duration"].asInt, native.durationDays)
            assertEquals(label, c["completedDays"].asJsonArray.map { it.asInt }, native.completedDays)
            val expectedDays = c["assignments"].asJsonArray
            assertEquals(label, expectedDays.size(), native.assignments.size)
            native.assignments.forEachIndexed { index, a ->
                val expected = expectedDays[index].asJsonObject
                assertEquals(label, expected["day"].asInt, a.dayNumber)
                assertEquals(label, expected["date"].asString, a.date)
                assertEquals(label, expected["pages"].asJsonArray.map { it.asInt }, a.items.flatMap { (it.pageStart..it.pageEnd).toList() })
            }
            val overview = PlannerEngine.getPlannerOverview(native, today)!!
            val expectedOverview = c["overview"].asJsonObject
            assertEquals(label, expectedOverview["completionRatio"].asFloat, overview.completionRatio, .0001f)
            assertEquals(label, expectedOverview["currentDayNumber"].asInt, overview.currentDayNumber)
            assertEquals(label, expectedOverview["remainingCount"].asInt, overview.remainingCount)
            val current = PlannerEngine.getCurrentAssignment(native, today)!!
            assertEquals(label, c["currentDay"].asInt, current.dayNumber)
            val progress = PlannerEngine.getAssignmentProgress(native, current)
            assertEquals(label, c["currentProgress"].asJsonObject["totalPagesCount"].asInt, progress.totalPagesCount)
            assertEquals(label, c["currentProgress"].asJsonObject["readPagesCount"].asInt, progress.readPagesCount)
            assertEquals(label, c["endDate"].asString, PlannerEngine.getPlanEndDate(native))
        }
    }
}
